import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.PropertySource;

@EnableCaching
@SpringBootApplication
@PropertySource("classpath:configuration.properties")
public class InfyGoBootCachingApplication {
    public static void main(String[] args) {
        SpringApplication.run(InfyGoBootCachingApplication.class, args);
    }
}

@PostMapping(value = "registerUser")
public ModelAndView addCustomer(@Valid @ModelAttribute("command") User user, BindingResult result, ModelMap model) {
    ...
